"""Settings that can be overridden with environment variables."""
import os


def get(name, default=None):
    """Return the environment variable `name`, or `default` when it is unset."""
    return os.environ.get(name, default)

"""Inventory queries."""


def total_quantity(items):
    """Sum the quantity of every item. Items are dicts with name and quantity."""
    return sum(item["quantity"] for item in items)


def find(items, name):
    """Return the item called `name`, or None."""
    for item in items:
        if item["name"] == name:
            return item
    return None

